using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed metadata retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Properties: {personInfo.Properties.Count}");

// 2. Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use options WITHOUT a resolver so resolution fails gracefully.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
{
    Console.WriteLine($"Probed metadata found: {probed!.Type.Name}");
}
else
{
    Console.WriteLine("Probed metadata NOT available (no exception thrown).");
}

// Confirm it also succeeds when a resolver IS present
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed2))
{
    var typed = (JsonTypeInfo<Person>)probed2!;
    Console.WriteLine($"TryGet succeeded — typed info for: {typed.Type.Name}");
}

public record Person(string Name, int Age);

